<?php
// Run once after importing database.sql and configuring config.php, then DELETE this file.
require __DIR__.'/bootstrap.php';$count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();if($count>0){http_response_code(403);exit('An admin already exists. Delete install.php.');}$done=false;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');if(!$email||strlen($pass)<12)$error='Provide a valid email and a password of at least 12 characters.';else{$q=$pdo->prepare('INSERT INTO admins(email,password_hash) VALUES(?,?)');$q->execute([$email,password_hash($pass,PASSWORD_DEFAULT)]);$done=true;}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title>Initial setup</title></head><body class="admin-login"><form method="post" class="login-card"><h1>Create admin account</h1><?php if($done):?><div class="notice">Admin created. Delete install.php now, then sign in at admin/login.php.</div><?php else:?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required></label><label>Password (12+ characters)<input type="password" name="password" minlength="12" required></label><button class="button full">CREATE ADMIN</button><?php endif;?></form></body></html>
